"""Build only the VT artifacts; no GUI, SIMD C++ runtime, or Xcode app."""
import os
from pathlib import Path
import subprocess
import sys

# Keep generated bytecode out of the recipe embedded in the conda package.
sys.dont_write_bytecode = True
from zig_cache import zig_executable

src = Path(os.environ['SRC_DIR'])
os.chdir(src)
cache = Path(os.environ.get('ZIG_GLOBAL_CACHE_DIR', src / 'zig-cache'))
os.environ['ZIG_GLOBAL_CACHE_DIR'] = str(cache)
zig = zig_executable()
# The library release ships its complete, unpacked offline dependency set.
packages = src / 'vt-deps'
platform = os.environ['target_platform']
prefix = Path(os.environ['LIBRARY_PREFIX'] if platform.startswith('win-') else os.environ['PREFIX'])
target = {'linux-64': 'x86_64-linux-gnu', 'linux-aarch64': 'aarch64-linux-gnu',
          'osx-arm64': 'aarch64-macos.13.0', 'osx-64': 'x86_64-macos.13.0', 'win-64': 'x86_64-windows-msvc'}[platform]
flags = []
if platform.startswith('linux-'):
    host = os.environ['HOST']
    sysroot = Path(os.environ['BUILD_PREFIX']) / host / 'sysroot'
    gcc = subprocess.check_output([f'{host}-gcc', '-print-libgcc-file-name'], text=True).strip()
    libc = src / 'conda-libc.txt'
    libc.write_text(f'include_dir={sysroot}/usr/include\nsys_include_dir={sysroot}/usr/include\n'
                    f'crt_dir={sysroot}/usr/lib64\nmsvc_lib_dir=\nkernel32_lib_dir=\n'
                    f'cc_dir={Path(gcc).parent}\ndarwin_sdk_dir=\n')
    flags = ['--sysroot', str(sysroot), '--libc', str(libc),
             '-Dbuild-glibc-version=' + os.environ['c_stdlib_version'] + '.0']
subprocess.run([zig, 'build', '-Demit-lib-vt=true', '-Demit-xcframework=false', '--prefix', str(prefix), '--system', str(packages),
                '-Dtarget=' + target, '-Dcpu=baseline', '-Doptimize=fast',
                '-Dsimd=false', '-Dapp-runtime=none', '-Demit-exe=false', '-Demit-docs=false',
                '-Demit-macos-app=false', *flags], check=True)
if platform.startswith('win-'):
    # Zig installs DLLs to bin and import/static libraries to lib.
    assert (prefix / 'bin/ghostty-vt.dll').is_file()
pcdir = prefix / 'lib/pkgconfig'
pcdir.mkdir(parents=True, exist_ok=True)
for name in ['libghostty-vt.pc', 'libghostty-vt-static.pc']:
    pc = pcdir / name
    # Use forward slashes for pkgconf on Windows too.
    text = '\n'.join('prefix=' + prefix.as_posix() if line.startswith('prefix=') else line
                     for line in pc.read_text().splitlines()) + '\n'
    if name.endswith('-static.pc'):
        # Windows headers otherwise declare the C API as dllimport.
        text = text.replace('Cflags: -I${includedir}', 'Cflags: -I${includedir} -DGHOSTTY_STATIC')
        if platform.startswith('win-'):
            text = text.replace('Libs: ${libdir}/ghostty-vt-static.lib',
                                'Libs: ${libdir}/ghostty-vt-static.lib -lntdll -lkernel32')
    pc.write_text(text)
